            $key = $order->items->sole()->digitalKeys()->sole();
            if ($damage === 'missing') {
                $key->delete();
            } elseif ($damage === 'reassigned') {
                $other = Order::create(['user_id' => User::factory()->create()->id, 'status' => 'pending_payment',
